151	async function uploadIcon(strapi: Core.Strapi, file: string, alt: string): Promise<number> {
152	  // Read from src/ (not dist/) so the SVGs do not need a build copy step.
153	  const filepath = path.join(strapi.dirs.app.root, 'src', 'seed', 'assets', file);
154	  const { size } = fs.statSync(filepath);
155	  const [uploaded] = await strapi.plugin('upload').service('upload').upload({
156	    data: { fileInfo: { name: file, alternativeText: alt, caption: alt } },
157	    files: { filepath, originalFilename: file, mimetype: 'image/svg+xml', size },
158	  });
159	  return uploaded.id;
160	}
