162	export async function seedCountries(strapi: Core.Strapi): Promise<void> {
163	  const total = await strapi.documents(UID).count({});
164	  if (total > 0) return;
165	
166	  for (const country of COUNTRIES) {
167	    const icon = country.icon ? await uploadIcon(strapi, country.icon.file, country.icon.alt) : undefined;
168	    await strapi.documents(UID).create({
169	      data: { code: country.code, name: country.name, order: country.order, active: country.active, legalAge: country.legalAge, currency: country.currency, numberLocale: country.numberLocale, driverAgeBands: DRIVER_BANDS, vehicleAgeBands: VEHICLE_BANDS, icon },
170	      status: 'published',
171	    });
172	  }
173	}
