238	export async function backfillLegalAge(strapi: Core.Strapi): Promise<void> {
239	  const rows = (await strapi.db.query(COUNTRY_UID).findMany({})) as Array<{
240	    id: number;
241	    legalAge?: number | null;
242	  }>;
243	  // Direct DB update covers both the draft and published rows without touching their publication state.
244	  for (const row of countriesNeedingLegalAge(rows)) {
245	    await strapi.db.query(COUNTRY_UID).update({ where: { id: row.id }, data: { legalAge: DEFAULT_LEGAL_AGE } });
246	  }
247	}
