254	    const country = await strapi.documents(COUNTRY_UID).findFirst({ filters: { code }, status: 'published' });
255	    if (!country) continue;
256	    for (const field of fields) {
257	      await strapi.documents(FIELD_UID).create({
258	        data: { ...field, required: true, country: country.documentId },
259	        status: 'published',
260	      });
261	    }
262	  }
263	}
