18	// Fictitious demo data. PE is inactive on purpose to demo FR-006.
19	const COUNTRIES: SeedCountry[] = [
20	  { code: 'CO', name: 'Colombia', order: 1, active: true, legalAge: 18, currency: 'COP', numberLocale: 'es-CO', icon: { file: 'co.svg', alt: 'Bandera de Colombia' } },
21	  { code: 'CL', name: 'Chile', order: 2, active: true, legalAge: 18, currency: 'CLP', numberLocale: 'es-CL', icon: { file: 'cl.svg', alt: 'Bandera de Chile' } },
