25	export interface AgeBand {
26	  fromAge: number;
27	  toAge: number;
28	  factor: number;
29	}
30	
31	// Same bands for every country (ADR 0005); editors adjust them per country in the admin.
32	export const DRIVER_BANDS: AgeBand[] = [
33	  { fromAge: 0, toAge: 24, factor: 1.2 },
34	  { fromAge: 25, toAge: 65, factor: 1.0 },
35	  { fromAge: 66, toAge: 120, factor: 1.15 },
36	];
37	export const VEHICLE_BANDS: AgeBand[] = [
38	  { fromAge: 0, toAge: 5, factor: 1.0 },
39	  { fromAge: 6, toAge: 10, factor: 1.1 },
40	  { fromAge: 11, toAge: 20, factor: 1.2 },
41	];
