43	const PRICING_DEFAULTS: Record<string, { currency: string; numberLocale: string }> = Object.fromEntries(
44	  COUNTRIES.map((c) => [c.code, { currency: c.currency, numberLocale: c.numberLocale }]),
45	);
46	
47	interface PricingRow {
48	  code?: string;
49	  currency?: string | null;
50	  numberLocale?: string | null;
51	  driverAgeBands?: unknown[] | null;
52	  vehicleAgeBands?: unknown[] | null;
53	}
54	
55	/**
56	 * Pure: the values a country row is missing, taken from the defaults. Only rows that predate US-02
57	 * (currency or numberLocale missing) are backfilled; once a row has both, it is never touched, so bands
58	 * an editor emptied on purpose stay empty. Within a pre-US-02 row, only empty bands are filled.
59	 */
60	export function pricingPatch(row: PricingRow): Record<string, unknown> {
61	  const patch: Record<string, unknown> = {};
62	  if (row.currency && row.numberLocale) return patch;
63	  const defaults = PRICING_DEFAULTS[row.code ?? ''];
64	  if (!row.currency && defaults) patch.currency = defaults.currency;
65	  if (!row.numberLocale && defaults) patch.numberLocale = defaults.numberLocale;
66	  if (!row.driverAgeBands?.length) patch.driverAgeBands = DRIVER_BANDS;
67	  if (!row.vehicleAgeBands?.length) patch.vehicleAgeBands = VEHICLE_BANDS;
68	  return patch;
69	}
70	
71	const BAND_KEYS = ['driverAgeBands', 'vehicleAgeBands'];
72	
73	type DateLike = string | Date | null | undefined;
74	
75	const toTime = (d: DateLike): number => (d ? new Date(d).getTime() : Number.NaN);
76	
77	/**
78	 * Pure: whether the draft may be published after the backfill wrote to it. Publishing copies the whole draft
79	 * to the published version, so it is only safe when the draft carries no pending editor changes, i.e. it was
80	 * not modified after it was last published. Only `publishedAt` is compared: the published row's `updatedAt`
81	 * is bumped by DB-layer writes such as backfillLegalAge, which would hide a pending draft edit (R-15). A
82	 * DB-layer write can only make the draft look changed, which errs on the safe side (warning, no publish).
83	 * No published version, or unreadable dates, means do not publish (never publish a draft that was not live).
84	 */
85	export function shouldPublishAfterBackfill(input: { draftUpdatedAt: DateLike; publishedAt: DateLike }): boolean {
86	  const published = toTime(input.publishedAt);
87	  const draft = toTime(input.draftUpdatedAt);
88	  if (Number.isNaN(published) || Number.isNaN(draft)) return false;
89	  return draft <= published;
90	}
91	
92	type DbRow = PricingRow & {
93	  id: number;
94	  documentId: string;
95	  publishedAt?: DateLike;
96	  updatedAt?: DateLike;
97	};
98	
99	/**
100	 * Existing databases get currency, locale and bands only on rows that predate US-02, never overwriting.
101	 * Scalars are written at the DB layer on each row (draft and published alike, like backfillLegalAge). The db
102	 * layer does not manage components, so the bands go through the Document Service. In Strapi 5,
103	 * `documents().update({ status: 'published' })` writes the draft and then publishes the WHOLE draft, which
104	 * would take unpublished editor changes live. So the bands are written to the draft only, and the draft is
105	 * published afterwards only if it had no pending changes (see shouldPublishAfterBackfill); otherwise a
106	 * warning names the country, whose published version lacks the bands until an editor publishes.
107	 */
108	export async function backfillCountryPricing(strapi: Core.Strapi): Promise<void> {
109	  const rows = (await strapi.db.query(UID).findMany({
110	    populate: { driverAgeBands: true, vehicleAgeBands: true },
111	  })) as unknown as DbRow[];
112	  const byDocument = new Map<string, DbRow[]>();
113	  for (const row of rows) byDocument.set(row.documentId, [...(byDocument.get(row.documentId) ?? []), row]);
114	
115	  for (const [documentId, versions] of byDocument) {
116	    const draft = versions.find((v) => !v.publishedAt);
117	    const published = versions.find((v) => v.publishedAt);
118	    const draftUpdatedAtBefore = draft?.updatedAt;
119	
120	    let bandsPatch: Record<string, unknown> = {};
121	    for (const row of versions) {
122	      const patch = pricingPatch(row);
123	      const scalars = Object.fromEntries(Object.entries(patch).filter(([k]) => !BAND_KEYS.includes(k)));
124	      if (Object.keys(scalars).length > 0) {
125	        await strapi.db.query(UID).update({ where: { id: row.id }, data: scalars });
126	      }
127	      if (row === (draft ?? published)) {
128	        bandsPatch = Object.fromEntries(Object.entries(patch).filter(([k]) => BAND_KEYS.includes(k)));
129	      }
130	    }
131	    if (Object.keys(bandsPatch).length === 0) continue;
132	
133	    await strapi.documents(UID).update({ documentId, data: bandsPatch as never, status: 'draft' });
134	    if (!published) continue;
135	    const code = (draft ?? published).code;
136	    if (
137	      shouldPublishAfterBackfill({
138	        draftUpdatedAt: draftUpdatedAtBefore,
139	        publishedAt: published.publishedAt,
140	      })
141	    ) {
142	      await strapi.documents(UID).publish({ documentId });
143	    } else {
144	      strapi.log.warn(
145	        `Country ${code}: age bands were added to the draft only because it has unpublished changes; the published version lacks the pricing until an editor publishes it.`,
146	      );
147	    }
148	  }
149	}
