      { key: 'documentNumber', maskedInSummary: null },
      { key: 'rut' },
      { key: 'email', maskedInSummary: null },
      { key: 'plate' },
    ];
    expect(rowsNeedingMaskedFlag(rows).map((r) => r.key)).toEqual(['documentNumber', 'rut']);
