    expect(TERMS_BY_COUNTRY.CO).not.toEqual(TERMS_BY_COUNTRY.CL);
  });

  it('adds nothing for a country without seeded terms (PE)', () => {
    expect(termsPatch({ code: 'PE', termsAndConditions: null })).toEqual({});
